let raw = $json.message && $json.message.content ? $json.message.content : ($json.content || $json.text || '');
raw = String(raw).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = { _parse_error: String(e), _raw: raw }; }
return parsed;

const trigger = $('Email received').first();
const binary = trigger.binary || {};
const out = [];
for (const key of Object.keys(binary)) {
  const b = binary[key];
  const name = String(b.fileName || '').toLowerCase();
  if (name.endsWith('.pdf') || name.endsWith('.doc') || name.endsWith('.docx')) {
    out.push({ json: { fileName: b.fileName, mimeType: b.mimeType }, binary: { data: b } });
  }
}
return out;

const cls = $('Parse classification').first().json || {};
const trig = $('Email received').first().json || {};
const folder = $('Create folder').first().json || {};
let uploads = [];
try { uploads = $('Upload attachment').all().map(i => i.json); } catch (e) { uploads = []; }
const resumeUrls = uploads.map(u => u.webViewLink).filter(Boolean);
const folderLink = folder.id ? ('https://drive.google.com/drive/folders/' + folder.id) : null;
let associations = Array.isArray(cls.resume_associations) ? cls.resume_associations : [];
associations = associations.map((a, idx) => Object.assign({}, a, { resume_url: resumeUrls[idx] || a.resume_url || null }));
const payload = {
  sender_email: trig.from || null,
  subject: trig.subject || null,
  mail_content: trig.text || trig.snippet || '',
  received_at: trig.date || null,
  webhook_intent: cls.webhook_intent || 'Cold candidate',
  job_title: cls.job_title != null ? cls.job_title : null,
  skill_channel_id: cls.skill_channel_id != null ? cls.skill_channel_id : null,
  primary_specialization: cls.primary_specialization != null ? cls.primary_specialization : null,
  mail_body_intent: cls.mail_body_intent != null ? cls.mail_body_intent : null,
  attachment_job_description: !!cls.attachment_job_description,
  attachment_pdf: !!cls.attachment_pdf,
  attachment_resumes: !!cls.attachment_resumes,
  drive_folder_link: folderLink,
  resume_drive_urls: resumeUrls,
  resume_associations: associations,
  summary_mail: cls.summary_mail || '',
  summary_candidates: cls.summary_candidates != null ? cls.summary_candidates : null,
  summary_interview_scores: cls.summary_interview_scores != null ? cls.summary_interview_scores : null,
  candidate_schedule_data: Array.isArray(cls.candidate_schedule_data) ? cls.candidate_schedule_data : [],
};
return [{ json: payload }];
